def get_questions(topic=None, difficulty=None):
    return [q for q in QUESTIONS if (not topic or q["topic"] == topic) and (not difficulty or q["difficulty"] == difficulty)]

def topics():
    return sorted({q["topic"] for q in QUESTIONS})

if __name__ == '__main__':
    import csv, json
    from config import QUESTIONS_PATH
    QUESTIONS_PATH.parent.mkdir(parents=True, exist_ok=True)
    with QUESTIONS_PATH.open('w', newline='', encoding='utf-8') as handle:
        writer=csv.DictWriter(handle,fieldnames=list(QUESTIONS[0]))
        writer.writeheader()
        for question in QUESTIONS:
            writer.writerow({**question,'options':json.dumps(question['options'],ensure_ascii=False)})
    print(f'Exported {len(QUESTIONS)} questions to {QUESTIONS_PATH}')
